from collections import defaultdict
from typing import Union, Optional

from robot.libraries.BuiltIn import BuiltIn
from taf.config.testline import ClassicalBts, RealEnb, Connection, CoreUnit, CommonUnit
from taf.sbts.oam.coam.admin import admin

from taf.rfrl.csv4all.resources.node.exceptions import GivenNodeIdNotFoundError, NodeInformationNotProvidedError
from taf.rfrl.csv4all.resources.node.node import Node
from taf.rfrl.csv4all.resources.utilities.decorators import function_wrapper, test_logger


class NodeFactory:

    @staticmethod
    @function_wrapper
    def create_node(node_alias: Optional[str] = None, node_vm: Union[str, dict] = None,
                    bts_host_ip: Optional[str] = "192.168.255.129", external_dcap_host: Optional[str] = None,
                    dcap_port: Optional[str] = "9443",
                    dcap_custom_profiles: Optional[dict] = None, hw_to_onair_timeout: Optional[int] = 900,
                    alarm_timer: Optional[int] = 60, testline_object: Union[ClassicalBts, RealEnb, CoreUnit] = None,
                    source_sw: Optional[str] = None, target_sw: Optional[str] = None,
                    custom_allowed_alarms: Union[str, list] = None,
                    temporary_allowed_alarms: Union[str, list] = None, critical_alarms: Union[str, list] = None,
                    pdu_config: Optional[list] = None, logs_dir: Optional[str] = None,
                    testline_scout_name: Optional[str] = None, use_dcap: Optional[bool] = False,
                    secondary_vm: Union[str, dict] = None, verify_syslog: Optional[bool] = True,
                    syslog_ignored_prints: Union[list, str] = None,
                    user_syslog_suspicious_prints: Union[list, str] = None, mumin_config: Optional[list] = None,
                    webem_username: str = 'Nemuadmin', webem_password: str = 'nemuuser',
                    node_ssh_username: str = "toor4nsn", node_ssh_password: str = "oZPS0POrRieRtu",
                    check_mplane: bool = True, oran_files: dict = None, airphone_details: dict = None,
                    check_amf: bool = True, admin_setup_timeout: int = 120, setup_energy_saving: bool = False,
                    ru_manager_yaml_file: Union[str, None] = None, **kwargs) -> Node:
        args = locals()
        kwargs = args.get('kwargs')
        del args['kwargs']
        args.update(kwargs)
        node = Node(**NodeFactory._get_parsed_node_args(args))
        test_logger(f"Setup for node: {node.mrbts_id}")
        node.setup_node()
        node.log_node_information()
        return node

    @staticmethod
    def _get_node_vm(taf_testline_object, return_secondary: bool = False) -> Union[dict, None]:
        """
    The _get_node_vm function is used to get the IP address and credentials of a node VM.

    :param taf_testline_object: Get the ip address and credentials of the vm
    :return: A dictionary of information about the node vm

    """

        def get_vm_details(device):
            vm_details = {
                'host': test_pc.default_ssh_connection_details.addr,
                'user': test_pc.default_ssh_connection_details.username or "ute",
                'password': test_pc.default_ssh_connection_details.password or "ute"
            }
            node_vm = NodeFactory._get_correct_node_vm(taf_testline_object, slave, device, vm_details,
                                                       return_secondary)
            if node_vm:
                return node_vm

        slave = getattr(taf_testline_object, "slave")
        node_vm_details = defaultdict()
        vm_details = None
        if return_secondary and not slave:
            return
        if return_secondary and slave:
            try:
                if isinstance(slave, RealEnb):
                    slave_system_module = getattr(slave.system_module, 'core_units', None) or \
                                          getattr(slave.system_module, 'common_units')
                    node_vm_details["bts_host_ip"] = slave_system_module[0].lmp_connection.addr or "192.168.255.7"
                elif isinstance(slave, ClassicalBts):
                    slave_system_module = getattr(slave.dus[0].airscale, 'core_units', None) or \
                                          getattr(slave.dus[0].airscale, 'common_units')
                    node_vm_details["bts_host_ip"] = slave_system_module[0].lmp_connection.addr or "192.168.255.7"
            except Exception as e:
                test_logger(e, "WARN")
                node_vm_details["bts_host_ip"] = "192.168.255.7"
        for test_pc in BuiltIn().get_variable_value("${tl.test_pcs}"):
            for connection_attr in test_pc.connections:
                if isinstance(connection_attr, Connection):
                    vm_details = get_vm_details(connection_attr.device)
                elif isinstance(connection_attr, CommonUnit):
                    vm_details = get_vm_details(connection_attr)
                elif isinstance(connection_attr, CoreUnit):
                    vm_details = get_vm_details(connection_attr)
                elif test_pc.connections[0] == taf_testline_object:
                    raise Exception("Please use latest format for test line init file")
                if vm_details:
                    node_vm_details.update(vm_details)
                    return node_vm_details

    @staticmethod
    def _get_correct_node_vm(taf_testline_object, slave, device, vm_node: dict, return_secondary):
        if isinstance(taf_testline_object, RealEnb):
            taf_testline_object = getattr(taf_testline_object.system_module, 'core_units', None) or \
                                  getattr(taf_testline_object.system_module, 'common_units')
            slave_system_module = getattr(slave.system_module, 'core_units', None) or \
                                  getattr(slave.system_module, 'common_units') if slave else None
        elif isinstance(taf_testline_object, ClassicalBts):
            taf_testline_object = getattr(taf_testline_object.dus[0].airscale, 'core_units', None) or \
                                  getattr(taf_testline_object.dus[0].airscale, 'common_units')
            slave_system_module = getattr(slave.dus[0].airscale, 'core_units', None) or \
                                  getattr(slave.dus[0].airscale, 'common_units') if slave else None
        else:
            return
        if return_secondary and device in slave_system_module:
            return vm_node
        elif return_secondary and device not in slave_system_module:
            return
        if device in taf_testline_object:
            return vm_node

    @staticmethod
    def get_node_by_alias(nodes_list: list, node_alias):
        for node in nodes_list:
            if node.node_alias == node_alias:
                return node
        raise GivenNodeIdNotFoundError(f"Searched ID {node_alias}")

    @staticmethod
    def _get_node_mrbts_id(node_args):
        testline_object = node_args.get("testline_object", None)
        if testline_object and testline_object.global_bts_id:
            node_mrbts_id = testline_object.global_bts_id
        else:
            temp_admin = admin()
            try:
                temp_admin.setup_admin(bts_host="192.168.255.129", username=node_args.get("webem_username"),
                                       password=node_args.get("webem_password"),
                                       remote_host=node_args["node_vm"].get("host"),
                                       remote_host_username=node_args["node_vm"].get("user"),
                                       remote_host_password=node_args["node_vm"].get("password"),
                                       timeout=120, alias="node_mrbts_admin")
                node_mrbts_id = temp_admin.get_bts_info(alias="node_mrbts_admin", timeout=1800).get("mrbtsID")
            except Exception as admin_exception:
                test_logger("Failed to get mrbtsID from node", "error")
                test_logger(admin_exception, "debug")
                raise
            finally:
                temp_admin.teardown_admin(alias="node_mrbts_admin")
        return node_mrbts_id

    @staticmethod
    def _get_vm_parameters(node_vm):
        if isinstance(node_vm, dict):
            assert all(param in node_vm.keys() for param in ["host", "user", "password"])
            return node_vm
        elif isinstance(node_vm, str):
            return {"host": node_vm, "user": "ute", "password": "ute"}
        return

    @staticmethod
    @function_wrapper
    def _get_parsed_node_args(node_args):
        if node_args.get("testline_object"):
            node_args["node_vm"] = NodeFactory._get_vm_parameters(
                NodeFactory._get_node_vm(node_args.get("testline_object")))
            node_args["secondary_vm"] = NodeFactory._get_vm_parameters(
                NodeFactory._get_node_vm(node_args.get("testline_object"), return_secondary=True))
            node_args["node_mrbts_id"] = NodeFactory._get_node_mrbts_id(node_args)
        elif not node_args.get("node_vm"):
            raise NodeInformationNotProvidedError
        else:
            node_args["node_vm"] = NodeFactory._get_vm_parameters(node_args.get("node_vm"))
            if node_args["node_vm"] and not node_args["node_vm"].get("bts_host_ip"):
                node_args["node_vm"]["bts_host_ip"] = "192.168.255.129"
            node_args["secondary_vm"] = NodeFactory._get_vm_parameters(node_args.get("secondary_vm"))
            if node_args["secondary_vm"] and not node_args["secondary_vm"].get("bts_host_ip"):
                node_args["secondary_vm"]["bts_host_ip"] = "192.168.255.7"
            node_args["node_mrbts_id"] = NodeFactory._get_node_mrbts_id(node_args)
        node_args.__delitem__("testline_object")
        node_args.__delitem__("mumin_config")

        return node_args
